/* ==== N=128 chain 4.4.8 ==== */
__attribute__((target("avx512f")))
void zttp_128_4_4_8_fwd_avx512(const double *zin, double *zout, const double *tw, size_t tile)
{
    _zt0d4f_body(zin, zout, tw + 0, (size_t)32, (size_t)32);
    if ((size_t)32 > tile)   /* stage 1: Len = 32, sweeps */
    {
#pragma GCC unroll 1
        for (size_t g = 0; g < (size_t)4; g++)
            _ztmgd4f_body(zout + g * (size_t)64, zout + g * (size_t)64, tw + 192, (size_t)8, (size_t)8);
    }
    if (tile)
    {
        const size_t ntile = (size_t)128 / tile;
#pragma GCC unroll 1
        for (size_t t = 0; t < ntile; t++)
        {
            double *B = zout + t * tile * 2;
            if ((size_t)32 <= tile)   /* stage 1: Len = 32 */
            {
#pragma GCC unroll 1
                for (size_t g = 0; g < tile / (size_t)32; g++)
                    _ztmgd4f_body(B + g * (size_t)64, B + g * (size_t)64, tw + 192, (size_t)8, (size_t)8);
            }
            _ztld8f_body(B, B, tw, (size_t)0, tile / (size_t)8);   /* last stage: Len = 8, in place */
        }
    }
    else
        _ztld8f_body(zout, zout, tw, (size_t)0, (size_t)16);   /* last stage, untiled: one sweep in place */
}

__attribute__((target("avx512f")))
void zttp_128_4_4_8_bwd_avx512(const double *zin, double *zout, const double *tw, size_t tile)
{
    if (tile)
    {
        const size_t ntile = (size_t)128 / tile;
#pragma GCC unroll 1
        for (size_t t = 0; t < ntile; t++)
        {
            const double *Bi = zin + t * tile * 2;
            double *B = zout + t * tile * 2;
            _ztld8b_body(Bi, B, tw, (size_t)0, tile / (size_t)8);   /* inverse of the last stage */
            if ((size_t)32 <= tile)   /* stage 1: Len = 32 */
            {
#pragma GCC unroll 1
                for (size_t g = 0; g < tile / (size_t)32; g++)
                    _ztmg4b_body(B + g * (size_t)64, B + g * (size_t)64, tw + 192, (size_t)8, (size_t)8);
            }
        }
    }
    else
        _ztld8b_body(zin, zout, tw, (size_t)0, (size_t)16);
    if ((size_t)32 > tile)   /* stage 1: Len = 32, sweeps */
    {
#pragma GCC unroll 1
        for (size_t g = 0; g < (size_t)4; g++)
            _ztmg4b_body(zout + g * (size_t)64, zout + g * (size_t)64, tw + 192, (size_t)8, (size_t)8);
    }
    _ztlf4b_body(zout, zout, tw + 0, (size_t)32, (size_t)32, (size_t)32);
}

